  `expBeforeDeath` bigint UNSIGNED NULL DEFAULT 0,
  `sp` int UNSIGNED NOT NULL DEFAULT 0,
  `karma` int UNSIGNED NULL DEFAULT NULL,
  `pvpkills` smallint UNSIGNED NULL DEFAULT NULL,
  `pkkills` smallint UNSIGNED NULL DEFAULT NULL,
  `clanid` int UNSIGNED NULL DEFAULT NULL,
