  `count` int NULL DEFAULT NULL,
  `enchant_level` int NULL DEFAULT NULL,
  `loc` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `loc_data` int NULL DEFAULT NULL,
  `time_of_use` int NULL DEFAULT NULL,
  `custom_type1` int NULL DEFAULT 0,
  `custom_type2` int NULL DEFAULT 0,
  `mana_left` decimal(5, 0) NOT NULL DEFAULT -1,
  `attributes` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `process` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
