  `first_owner_id` int NOT NULL,
  `creation_time` decimal(16, 0) NULL DEFAULT NULL,
  `data` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
