  `pvp_level` tinyint NOT NULL DEFAULT 1 COMMENT 'Nível do enhancement PvP (1-3)',
  PRIMARY KEY (`object_id`) USING BTREE,
  INDEX `key_owner_id`(`owner_id`) USING BTREE,
  INDEX `key_loc`(`loc`) USING BTREE,
  INDEX `key_item_id`(`item_id`) USING BTREE,
  INDEX `key_time_of_use`(`time_of_use`) USING BTREE,
  INDEX `idx_is_pvp`(`is_pvp`) USING BTREE,
  INDEX `idx_items_pvp`(`is_pvp`, `pvp_level`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

