-- ----------------------------
-- Table structure for marketplace_transactions
-- ----------------------------
DROP TABLE IF EXISTS `marketplace_transactions`;
CREATE TABLE `marketplace_transactions`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `transfer_id` int NOT NULL COMMENT 'ID da transferência',
  `transaction_type` enum('sale','purchase','fee','refund','claim') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tipo da transação',
  `amount` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT 'Valor da transação',
  `currency` enum('adena','l_coins','real') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'adena',
  `user_uuid` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'UUID do usuário envolvido',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'Observações da transação',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `processed_at` timestamp NULL DEFAULT NULL COMMENT 'Data de processamento',
  `status` enum('pending','completed','failed','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_transfer_id`(`transfer_id` ASC) USING BTREE,
  INDEX `idx_transaction_type`(`transaction_type` ASC) USING BTREE,
  INDEX `idx_user_uuid`(`user_uuid` ASC) USING BTREE,
  INDEX `idx_created_at`(`created_at` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_marketplace_transactions_composite`(`status` ASC, `created_at` ASC, `transaction_type` ASC) USING BTREE,
  CONSTRAINT `fk_marketplace_transaction_transfer` FOREIGN KEY (`transfer_id`) REFERENCES `character_transfers` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Transações do marketplace' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of marketplace_transactions
-- ----------------------------

