-- ----------------------------
-- View structure for fame_statistics
-- ----------------------------
DROP VIEW IF EXISTS `fame_statistics`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `fame_statistics` AS select `c`.`char_name` AS `char_name`,`c`.`pvp_fame` AS `current_fame`,(select count(0) from `pvp_fame_history` where ((`pvp_fame_history`.`char_id` = `c`.`charId`) and (`pvp_fame_history`.`fame_change` > 0))) AS `fame_gains`,(select sum(`pvp_fame_history`.`fame_change`) from `pvp_fame_history` where ((`pvp_fame_history`.`char_id` = `c`.`charId`) and (`pvp_fame_history`.`fame_change` > 0))) AS `total_fame_earned`,(select sum(abs(`pvp_fame_history`.`fame_change`)) from `pvp_fame_history` where ((`pvp_fame_history`.`char_id` = `c`.`charId`) and (`pvp_fame_history`.`fame_change` < 0))) AS `total_fame_spent`,(select count(0) from `weapon_upgrade_log` where ((`weapon_upgrade_log`.`char_id` = `c`.`charId`) and (`weapon_upgrade_log`.`fame_cost` > 0))) AS `fame_upgrades` from `characters` `c` where ((`c`.`pvp_fame` > 0) or `c`.`charId` in (select distinct `pvp_fame_history`.`char_id` from `pvp_fame_history`)) order by `c`.`pvp_fame` desc;

-- ----------------------------
-- Procedure structure for AddPlayerFame
-- ----------------------------
DROP PROCEDURE IF EXISTS `AddPlayerFame`;
delimiter ;;
CREATE PROCEDURE `AddPlayerFame`(IN player_name VARCHAR(35),
    IN fame_amount INT,
    IN source_type VARCHAR(50),
    IN source_details VARCHAR(255))
BEGIN
    DECLARE player_id INT;
    DECLARE current_fame INT;
    DECLARE new_fame INT;
    
    -- Buscar ID do player
    SELECT charId, pvp_fame INTO player_id, current_fame 
    FROM characters 
    WHERE char_name = player_name 
    COLLATE utf8_general_ci 
    LIMIT 1;
    
    IF player_id IS NOT NULL THEN
        -- Calcular novo Fame
        SET new_fame = current_fame + fame_amount;
        IF new_fame < 0 THEN
            SET new_fame = 0;
        END IF;
        
        -- Atualizar Fame do player
        UPDATE characters 
        SET pvp_fame = new_fame 
        WHERE charId = player_id;
        
        -- Registrar no histórico
        VALUES (player_id, player_name, fame_amount, new_fame, source_type, source_details);
        
        SELECT CONCAT('Fame updated for ', player_name, ': ', current_fame, ' -> ', new_fame) as result;
    ELSE
        SELECT CONCAT('Player not found: ', player_name) as result;
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Function structure for GetFameRank
-- ----------------------------
DROP FUNCTION IF EXISTS `GetFameRank`;
delimiter ;;
CREATE FUNCTION `GetFameRank`(player_char_id INT)
 RETURNS int
  READS SQL DATA 
  DETERMINISTIC
BEGIN
    DECLARE player_rank INT DEFAULT 0;
    
    SELECT COUNT(*) + 1 INTO player_rank
    FROM characters 
    WHERE pvp_fame > (SELECT pvp_fame FROM characters WHERE charId = player_char_id);
    
    RETURN player_rank;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_AccountCreate
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_AccountCreate`;
delimiter ;;
CREATE PROCEDURE `lip_AccountCreate`(IN `sAccountName` VARCHAR(32), IN `sAccountPasswordHash` VARCHAR(255))
BEGIN
    INSERT LOW_PRIORITY INTO `accounts` (
        `login`,
        `password`
    ) VALUES (
        sAccountName,
        sAccountPasswordHash
    );
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_AccountLoad
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_AccountLoad`;
delimiter ;;
CREATE PROCEDURE `lip_AccountLoad`(IN `sAccountName` VARCHAR(32))
BEGIN
    SELECT 
        `a`.`password` AS `password`, 
        `a`.`accessLevel` AS `accessLevel`, 
        `a`.`lastServerId` AS `lastServerId`, 
        `a`.`lastIP` AS `lastIP`, 
        `a`.`lastactive` AS `lastactive`, 
        `a`.`l2email` AS `email`
    FROM 
        `accounts` `a` 
    WHERE 
        `a`.`login` = sAccountName;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_AccountUpdate
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_AccountUpdate`;
delimiter ;;
CREATE PROCEDURE `lip_AccountUpdate`(IN `sAccountName` VARCHAR(32), IN `sAccountPasswordHash` VARCHAR(255), IN `iAccessLevel` TINYINT(6), IN `iLastServerId` INT(4), IN `sLastIp` VARCHAR(15), IN `iLastActive` INT(11), IN `sEmail` VARCHAR(45))
BEGIN
    UPDATE LOW_PRIORITY 
        `accounts` 
    SET
        `password` = sAccountPasswordHash,
        `accessLevel` = iAccessLevel,
        `lastServerId` = iLastServerId,
        `lastIP` = sLastIp,
        `lastactive` = iLastActive,
        `l2email` = sEmail
    WHERE
        `login` = sAccountName
    LIMIT 1;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_DeleteItem
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_DeleteItem`;
delimiter ;;
CREATE PROCEDURE `lip_DeleteItem`(IN `iItemID` INTEGER UNSIGNED)
BEGIN
  DELETE FROM `items` WHERE `items`.`item_id` = iItemID LIMIT 1;
  DELETE FROM `items_duration` WHERE `items_duration`.`item_id` = iItemID LIMIT 1;
  DELETE FROM `items_period` WHERE `items_period`.`item_id` = iItemID LIMIT 1;
  DELETE FROM `items_attributes` WHERE `items_attributes`.`item_id` = iItemID LIMIT 1;
  DELETE FROM `items_variation` WHERE `items_variation`.`item_id` = iItemID LIMIT 1;  
  DELETE FROM `items_options` WHERE `items_options`.`item_id` = iItemID LIMIT 1;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_ex_PawnShopDeleteItem
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_ex_PawnShopDeleteItem`;
delimiter ;;
CREATE PROCEDURE `lip_ex_PawnShopDeleteItem`(IN `iPawnShopId` INTEGER UNSIGNED)
