  DELETE FROM `pawnshop` WHERE `id` = iPawnShopId;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_ex_PawnShopLoadItems
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_ex_PawnShopLoadItems`;
delimiter ;;
CREATE PROCEDURE `lip_ex_PawnShopLoadItems`()
BEGIN
  SELECT SQL_NO_CACHE
    `ps`.`id` AS `id`,
    `ps`.`ownerId` AS `ownerId`,
    `ps`.`itemType` AS `itemType`,
    `ps`.`amount` AS `amount`,
    `ps`.`enchantLevel` AS `enchantLevel`,
    `ps`.`currency` AS `currency`,
    `ps`.`price` AS `price`,
    `ps`.`varOpt1` AS `varOpt1`,
    `ps`.`varOpt2` AS `varOpt2`
  FROM `pawnshop` `ps`;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_ex_PawnShopStoreItem
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_ex_PawnShopStoreItem`;
delimiter ;;
CREATE PROCEDURE `lip_ex_PawnShopStoreItem`(IN `iPawnShopId` INTEGER UNSIGNED, IN `iOwnerId` INTEGER UNSIGNED, IN `iItemType` MEDIUMINT UNSIGNED, IN `iAmount` INTEGER UNSIGNED, IN `iEnchant` SMALLINT UNSIGNED, IN `iCurrencyTypeType` MEDIUMINT UNSIGNED, IN `iPrice` INTEGER UNSIGNED, IN `iVarStat1` SMALLINT UNSIGNED, IN `iVarStat2` SMALLINT UNSIGNED)
BEGIN
  REPLACE LOW_PRIORITY INTO `pawnshop`(
    `id`,
    `ownerId`,
    `itemType`,
    `amount`,
    `enchantLevel`,
    `currency`,
    `price`,
    `varOpt1`,
    `varOpt2`
  ) VALUES (
    iPawnShopId,
    iOwnerId,
    iItemType,
    iAmount,
    iEnchant,
    iCurrencyTypeType,
    iPrice,
    iVarStat1,
    iVarStat2
  );
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_GetItem
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_GetItem`;
delimiter ;;
CREATE PROCEDURE `lip_GetItem`(IN `iItemID` INTEGER UNSIGNED)
BEGIN
  SELECT SQL_NO_CACHE 
    `i`.`item_id` AS `item_id`,
    `i`.`owner_id` AS `owner_id`,
    `i`.`item_type` AS `item_type`,
    `i`.`amount` AS `amount`,
    `i`.`location` AS `location`,
    `i`.`slot` AS `slot`,
    `i`.`enchant` AS `enchant`,
    IFNULL(`id`.`duration`, -9999) AS `duration`,
    IFNULL(`ip`.`period`, -1) AS `period`,
    IFNULL(`ia`.`attack_type`, -2) AS `attack_attr_type`,
    IFNULL(`ia`.`attack_value`, 0) AS `attack_attr_val`,
    IFNULL(`ia`.`defence_fire`, 0) AS `defence_attr_fire`,
    IFNULL(`ia`.`defence_water`, 0) AS `defence_attr_water`,
    IFNULL(`ia`.`defence_wind`, 0) AS `defence_attr_wind`,
    IFNULL(`ia`.`defence_earth`, 0) AS `defence_attr_earth`,
    IFNULL(`ia`.`defence_holy`, 0) AS `defence_attr_holy`,
    IFNULL(`ia`.`defence_unholy`, 0) AS `defence_attr_unholy`,
    IFNULL(`iv`.`stat1`, 0) AS `variation_stat1`,
    IFNULL(`iv`.`stat2`, 0) AS `variation_stat2`,
    IFNULL(`io`.`blessed`, 0) AS `blessed`,
    IFNULL(`io`.`damaged`, 0) AS `damaged`,
    IFNULL(`io`.`energy`, 0) AS `item_energy`,
    IFNULL(`io`.`flags`, 0) AS `custom_flags`,
    IFNULL(`io`.`item_vis_type`, 0) AS `item_vis_type`
  FROM
    `items` `i`
    LEFT JOIN 
      `items_duration` `id`
    ON
      `id`.`item_id` = `i`.`item_id` 
    LEFT JOIN
      `items_period` `ip`
    ON
      `ip`.`item_id` = `i`.`item_id` 
    LEFT JOIN
      `items_attributes` `ia`
    ON
      `ia`.`item_id` = `i`.`item_id` 
    LEFT JOIN
      `items_variation` `iv`
    ON
      `iv`.`item_id` = `i`.`item_id` 
    LEFT JOIN
      `items_options` `io`
    ON
      `io`.`item_id` = `i`.`item_id` 
  WHERE `i`.`item_id` = iItemID LIMIT 1;
END
;;
delimiter ;

