-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_RepairePlayer`;
delimiter ;;
CREATE PROCEDURE `lip_RepairePlayer`(IN `iPayerObjID` INT(10) UNSIGNED)
BEGIN
	UPDATE `characters` SET `x` = 17867, `y` = 170259, `z` = -3503 WHERE `obj_Id` = iPayerObjID LIMIT 1;
	DELETE FROM `character_effects_save` WHERE `object_id`= iPayerObjID;
	UPDATE `items` SET `location` = "INVENTORY" WHERE `location` = "PAPERDOLL" AND `owner_id` = iPayerObjID;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for lip_StoreItem
-- ----------------------------
DROP PROCEDURE IF EXISTS `lip_StoreItem`;
delimiter ;;
CREATE PROCEDURE `lip_StoreItem`(IN `iItemID` INTEGER UNSIGNED, IN `iOwnerID` INTEGER UNSIGNED, IN `iItemType` MEDIUMINT UNSIGNED, IN `iAmount` BIGINT, IN `iSlot` INTEGER, IN `eLoc` ENUM('VOID','INVENTORY','PAPERDOLL','WAREHOUSE','FREIGHT','CLANWH','MAIL','PET_INVENTORY','PET_PAPERDOLL'), IN `iEnchant` SMALLINT UNSIGNED, IN `iDuration` INTEGER, IN `iPeriod` INTEGER, IN `iAttackType` TINYINT, IN `iAttackVal` SMALLINT, IN `iDefFire` SMALLINT, IN `iDefWater` SMALLINT, IN `iDefWind` SMALLINT, IN `iDefEarth` SMALLINT, IN `iDefHoly` SMALLINT, IN `iDefUnholy` SMALLINT, IN `iVariStat1` SMALLINT UNSIGNED, IN `iVariStat2` SMALLINT UNSIGNED, IN `iBlessed` INTEGER, IN `iDamaged` INTEGER, IN `iItemEnergy` INTEGER, IN `iCustomFlags` INTEGER UNSIGNED, IN `iItemVisType` MEDIUMINT UNSIGNED)
entry: BEGIN
  DECLARE iRowCount INTEGER DEFAULT 0;
  IF (iAmount <= 0) OR (iDuration = 0) OR (iPeriod = 0) OR (iOwnerID = 0) THEN 
    CALL `lip_DeleteItem`(iItemID);
    LEAVE entry;
  END IF;
  
  INSERT LOW_PRIORITY INTO `items` (
    `item_id`,
    `owner_id`,
    `item_type`,
    `amount`,
    `location`,
    `slot`,
    `enchant`
  ) VALUES (
    iItemID,
    iOwnerID,
    iItemType,
    iAmount,
    eLoc,
    iSlot,
    iEnchant
  ) ON DUPLICATE KEY UPDATE 
    `owner_id` = iOwnerID,
    `item_type` = iItemType,
    `amount` = iAmount,
    `location` = eLoc,
    `slot` = iSlot,
    `enchant` = iEnchant;
  
  SET iRowCount = ROW_COUNT();
  
  
  
  CASE 
    WHEN iRowCount = 1 THEN 
      BEGIN
        IF iDuration > 0 THEN 
          INSERT LOW_PRIORITY INTO `items_duration` (
            `item_id`,
            `duration`
          ) VALUES (
            iItemID,
            iDuration
          ) ON DUPLICATE KEY UPDATE
            `duration` = iDuration;
          
        END IF;
        
        IF iPeriod > 0 THEN 
          INSERT LOW_PRIORITY INTO `items_period` (
            `item_id`,
            `period`
          ) VALUES (
            iItemID,
            iPeriod
          ) ON DUPLICATE KEY UPDATE
            `period` = iPeriod;
          
        END IF;
        
        IF ((iAttackType > -2) AND (iAttackVal > 0)) OR 
           (iDefFire > 0) OR (iDefWater > 0) OR 
           (iDefWind > 0) OR (iDefEarth > 0) OR 
           (iDefHoly > 0) OR (iDefUnholy > 0) THEN
          INSERT LOW_PRIORITY INTO `items_attributes` (
            `item_id`,
            `attack_type`,
            `attack_value`,
            `defence_fire`,
            `defence_water`,
            `defence_wind`,
            `defence_earth`,
            `defence_holy`,
            `defence_unholy`
          ) VALUES (
            iItemID,
            iAttackType,
            iAttackVal,
            iDefFire,
            iDefWater,
            iDefWind,
            iDefEarth,
            iDefHoly,
            iDefUnholy
          ) ON DUPLICATE KEY UPDATE
            `attack_type` = iAttackType,
            `attack_value` = iAttackVal,
            `defence_fire` = iDefFire,
            `defence_water` = iDefWater,
            `defence_wind` = iDefWind,
            `defence_earth` = iDefEarth,
            `defence_holy` = iDefHoly,
            `defence_unholy` = iDefUnholy;

          
        END IF;
      
        IF (iVariStat1 > 0) OR (iVariStat2 > 0) THEN 
          INSERT LOW_PRIORITY INTO `items_variation` (
            `item_id`,
            `stat1`,
            `stat2`
          ) VALUES (
            iItemID,
            iVariStat1,
            iVariStat2
          ) ON DUPLICATE KEY UPDATE
            `stat1` = iVariStat1,
            `stat2` = iVariStat2;
          
        END IF;
        
        IF (iBlessed > 0) OR (iDamaged > 0) OR (iItemEnergy > 0) OR (iCustomFlags > 0) OR (iItemVisType > 0) THEN 
          INSERT LOW_PRIORITY INTO `items_options` (
            `item_id`,
            `blessed`,
            `damaged`,
            `energy`,
            `flags`,
            `item_vis_type`
          ) VALUES (
            iItemID,
            iBlessed,
            iDamaged,
            iItemEnergy,
            iCustomFlags,
            iItemVisType
          ) ON DUPLICATE KEY UPDATE
            `blessed` = iBlessed,
            `damaged` = iDamaged,
            `energy` = iItemEnergy,
            `flags` = iCustomFlags,
            `item_vis_type` = iItemVisType;
          
        END IF;
      END;
    WHEN (iRowCount = 0) OR (iRowCount = 2) OR (iRowCount = 3) THEN 
      BEGIN
        IF iDuration > 0 THEN
          UPDATE LOW_PRIORITY `items_duration` SET `duration` = iDuration WHERE `item_id` = iItemID LIMIT 1;









        END IF;
        
        IF iPeriod > 0 THEN
          UPDATE LOW_PRIORITY `items_period` SET `period` = iPeriod WHERE `item_id` = iItemID LIMIT 1;









        END IF;
        
        IF ((iAttackType > -2) AND (iAttackVal > 0)) OR 
           (iDefFire > 0) OR (iDefWater > 0) OR 
           (iDefWind > 0) OR (iDefEarth > 0) OR 
           (iDefHoly > 0) OR (iDefUnholy > 0) THEN
          INSERT LOW_PRIORITY INTO `items_attributes` ( 
            `item_id`,
            `attack_type`,
            `attack_value`,
            `defence_fire`,
            `defence_water`,
            `defence_wind`,
            `defence_earth`,
            `defence_holy`,
            `defence_unholy`
          ) VALUES (
            iItemID,
            iAttackType,
            iAttackVal,
            iDefFire,
            iDefWater,
            iDefWind,
            iDefEarth,
            iDefHoly,
            iDefUnholy
          ) ON DUPLICATE KEY UPDATE 
            `attack_type` = iAttackType,
            `attack_value` = iAttackVal,
            `defence_fire` = iDefFire,
            `defence_water` = iDefWater,
            `defence_wind` = iDefWind,
            `defence_earth` = iDefEarth,
            `defence_holy` = iDefHoly,
            `defence_unholy` = iDefUnholy;
          
        ELSE 
          DELETE LOW_PRIORITY FROM `items_attributes` WHERE `item_id` = iItemID LIMIT 1;
          
        END IF;
        
        
        IF (iVariStat1 > 0) OR (iVariStat2 > 0) THEN 
            `item_id`,
            `stat1`,
            `stat2`
          ) VALUES (
            iItemID,
            iVariStat1,
            iVariStat2
          ) ON DUPLICATE KEY UPDATE 
            `stat1` = iVariStat1,
            `stat2` = iVariStat2;
          
        ELSE 
          DELETE LOW_PRIORITY FROM `items_variation` WHERE `item_id` = iItemID LIMIT 1;
          
        END IF;
        
        IF (iBlessed > 0) OR (iDamaged > 0) OR (iItemEnergy > 0) OR (iCustomFlags > 0) OR (iItemVisType > 0) THEN 
          INSERT LOW_PRIORITY INTO `items_options` (
            `item_id`,
            `blessed`,
            `damaged`,
            `energy`,
            `flags`,
            `item_vis_type`
          ) VALUES (
            iItemID,
            iBlessed,
            iDamaged,
            iItemEnergy,
            iCustomFlags,
            iItemVisType
          ) ON DUPLICATE KEY UPDATE
            `blessed` = iBlessed,
            `damaged` = iDamaged,
            `energy` = iItemEnergy,
            `flags` = iCustomFlags,
            `item_vis_type` = iItemVisType;
          
        ELSE 
          DELETE LOW_PRIORITY FROM `items_options` WHERE `item_id` = iItemID LIMIT 1;
          
        END IF;
      END;
    ELSE
      BEGIN
        
        
        CALL `Unexpected ROW_COUNT() result in lip_StoreItem`;
      END;
  END CASE;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
